/* ─── Data structures ─── */
typedef struct {
    float h_backbone[SOMA_BACKBONE_H];         /* Backbone hidden state */
    int8_t h_backbone_q[SOMA_BACKBONE_H];      /* Quantized backbone hidden */
    float h_experts[SOMA_MAX_JOINTS][SOMA_EXPERT_H]; /* Expert hidden states */
    int8_t h_experts_q[SOMA_MAX_JOINTS][SOMA_EXPERT_H]; /* Quantized */
    float cpg_phase[SOMA_N_CPG];               /* CPG oscillator phases */
    float prev_tau[SOMA_MAX_JOINTS];           /* Previous torques (for rate limit) */
} soma_state_t;

typedef struct {
    float base_quat[4];                        /* Base orientation quaternion */
    float base_gyro[3];                        /* Angular velocity */
    float base_linvel[3];                      /* Linear velocity */
    float base_height;                         /* Base height above ground */
    float base_rpy[3];                         /* Roll, pitch, yaw */
    float joint_q[SOMA_NU];                    /* Joint positions */
    float joint_qd[SOMA_NU];                   /* Joint velocities */
    float contact_force[SOMA_NU][3];           /* Per-joint contact forces */
    float descriptors[SOMA_NU][SOMA_DESC_DIM]; /* Joint physical descriptors */
    float joint_mask[SOMA_MAX_JOINTS];         /* Active joint mask */
} soma_obs_t;

typedef struct {
    float locomotion[4];   /* vx, vy, yaw_rate, gait_speed */
    float posture[3];      /* body_height, body_pitch, body_roll */
    float ee_right[8];     /* pos(3) + orn(4) + grip_force(1) */
    float ee_left[8];      /* pos(3) + orn(4) + grip_force(1) */
    float impedance[3];    /* stiffness mode */
} soma_cmd_t;

